using Microsoft.EntityFrameworkCore; using OutreachFlow.Application.Campaigns; using OutreachFlow.Domain.Campaigns;
namespace OutreachFlow.Infrastructure.Persistence.Repositories;
public sealed class CampaignRepository(OutreachFlowDbContext db) : ICampaignRepository
{ public Task AddAsync(Campaign item,CancellationToken ct=default)=>db.Campaigns.AddAsync(item,ct).AsTask(); public Task<Campaign?> GetByIdAsync(Guid id,CancellationToken ct=default)=>db.Campaigns.FindAsync([id],ct).AsTask(); public async Task<IReadOnlyList<Campaign>> ListAsync(CancellationToken ct=default)=>await db.Campaigns.OrderBy(x=>x.Name).ToArrayAsync(ct); public async Task<IReadOnlyList<CampaignContact>> ContactsAsync(Guid id,CancellationToken ct=default)=>await db.CampaignContacts.Where(x=>x.CampaignId==id).ToArrayAsync(ct); public async Task<IReadOnlyList<CampaignContactGroup>> GroupsAsync(Guid id,CancellationToken ct=default)=>await db.CampaignContactGroups.Where(x=>x.CampaignId==id).ToArrayAsync(ct); public async Task<IReadOnlyList<CampaignAttachment>> AttachmentsAsync(Guid id,CancellationToken ct=default)=>await db.CampaignAttachments.Where(x=>x.CampaignId==id).ToArrayAsync(ct); public async Task ReplaceAsync(Guid id,IReadOnlyList<CampaignContact> contacts,IReadOnlyList<CampaignContactGroup> groups,IReadOnlyList<CampaignAttachment> attachments,CancellationToken ct=default) { db.CampaignContacts.RemoveRange(await db.CampaignContacts.Where(x=>x.CampaignId==id).ToArrayAsync(ct)); db.CampaignContactGroups.RemoveRange(await db.CampaignContactGroups.Where(x=>x.CampaignId==id).ToArrayAsync(ct)); db.CampaignAttachments.RemoveRange(await db.CampaignAttachments.Where(x=>x.CampaignId==id).ToArrayAsync(ct)); await db.CampaignContacts.AddRangeAsync(contacts,ct); await db.CampaignContactGroups.AddRangeAsync(groups,ct); await db.CampaignAttachments.AddRangeAsync(attachments,ct); } public void Remove(Campaign item)=>db.Campaigns.Remove(item); }
